/**
 * @fileoverview Wraps browser MCP tools (discovered from `chrome-devtools-mcp`)
 * as standard declarative tools usable by the browser agent, plus a composite
 * `type_text` convenience tool.
 */

import type {
  PolicyUpdateOptions,
  ToolCallConfirmationDetails,
  ToolInvocation,
  ToolMcpConfirmationDetails,
  ToolResult,
} from '../../tools/tools.js';
import {
  BaseDeclarativeTool,
  BaseToolInvocation,
  Kind,
  type DeclarativeTool,
  type ToolConfirmationOutcome,
} from '../../tools/tools.js';
import type { MessageBus } from '../../confirmation-bus/message-bus.js';
import { ToolErrorType } from '../../tools/tool-error.js';
import { BROWSER_MCP_SERVER_NAME } from './browserManager.js';
import type { BrowserManager } from './browserManager.js';

type ToolParams = Record<string, unknown>;

/**
 * Extracts and concatenates the textual content from an MCP tool result.
 */
function extractText(content: Array<{ type: string; text?: string }>): string {
  return content
    .filter((item) => item.type === 'text' && item.text)
    .map((item) => item.text)
    .join('\n');
}

/**
 * Invocation for a single browser MCP tool. Delegates execution to the
 * {@link BrowserManager} and normalizes the result into a {@link ToolResult}.
 */
class BrowserMcpToolInvocation extends BaseToolInvocation<
  ToolParams,
  ToolResult
> {
  constructor(
    private readonly browserManager: BrowserManager,
    private readonly underlyingToolName: string,
    params: ToolParams,
    messageBus: MessageBus,
    _toolName?: string,
    _toolDisplayName?: string,
  ) {
    super(params, messageBus, _toolName, _toolDisplayName);
  }

  getDescription(): string {
    return `${this._toolName ?? this.underlyingToolName}(${JSON.stringify(
      this.params,
    )})`.slice(0, 200);
  }

  override getPolicyUpdateOptions(
    _outcome: ToolConfirmationOutcome,
  ): PolicyUpdateOptions | undefined {
    return { mcpName: BROWSER_MCP_SERVER_NAME };
  }

  override async shouldConfirmExecute(
    _abortSignal: AbortSignal,
  ): Promise<ToolCallConfirmationDetails | false> {
    const confirmationDetails: ToolMcpConfirmationDetails = {
      type: 'mcp',
      title: 'Confirm Browser Action',
      serverName: BROWSER_MCP_SERVER_NAME,
      toolName: this._toolName ?? this.underlyingToolName,
      toolDisplayName:
        this._toolDisplayName ?? this._toolName ?? this.underlyingToolName,
      toolArgs: this.params,
      onConfirm: async (outcome: ToolConfirmationOutcome) => {
        await this.publishPolicyUpdate(outcome);
      },
    };
    return confirmationDetails;
  }

  async execute(signal: AbortSignal): Promise<ToolResult> {
    try {
      const result = await this.browserManager.callTool(
        this.underlyingToolName,
        this.params,
        signal,
      );
      const textContent = extractText(result.content ?? []);

      if (result.isError) {
        return {
          llmContent: `Error: ${textContent}`,
          returnDisplay: textContent,
          error: { message: textContent, type: ToolErrorType.MCP_TOOL_ERROR },
        };
      }

      return {
        llmContent: textContent,
        returnDisplay: textContent,
        error: undefined,
      };
    } catch (error) {
      const errorMsg = error instanceof Error ? error.message : String(error);
      return {
        llmContent: `Error: ${errorMsg}`,
        returnDisplay: errorMsg,
        error: { message: errorMsg, type: ToolErrorType.EXECUTION_FAILED },
      };
    }
  }
}

/**
 * Declarative tool that wraps a browser MCP tool.
 */
class BrowserMcpTool extends BaseDeclarativeTool<ToolParams, ToolResult> {
  constructor(
    private readonly browserManager: BrowserManager,
    messageBus: MessageBus,
    name: string,
    description: string,
    parameterSchema: unknown,
    private readonly underlyingToolName: string,
  ) {
    super(
      name,
      name,
      description,
      Kind.Other,
      parameterSchema,
      messageBus,
      /* isOutputMarkdown */ true,
      /* canUpdateOutput */ false,
    );
  }

  protected createInvocation(
    params: ToolParams,
    messageBus: MessageBus,
    _toolName?: string,
    _toolDisplayName?: string,
  ): ToolInvocation<ToolParams, ToolResult> {
    return new BrowserMcpToolInvocation(
      this.browserManager,
      this.underlyingToolName,
      params,
      messageBus,
      _toolName,
      _toolDisplayName,
    );
  }
}

/**
 * Parameter schema for the composite `type_text` tool.
 */
const TYPE_TEXT_SCHEMA = {
  type: 'object',
  properties: {
    uid: {
      type: 'string',
      description:
        'The uid of the target input element (from a page snapshot). Optional if an element is already focused.',
    },
    text: {
      type: 'string',
      description: 'The text to type into the element.',
    },
  },
  required: ['text'],
};

/**
 * Builds the composite `type_text` tool. This is always included regardless of
 * which tools the MCP server advertises.
 */
function createTypeTextTool(
  browserManager: BrowserManager,
  messageBus: MessageBus,
): DeclarativeTool<ToolParams, ToolResult> {
  return new BrowserMcpTool(
    browserManager,
    messageBus,
    'type_text',
    'Type text into an input element on the page. A convenience wrapper that ' +
      'fills the target element with the provided text.',
    TYPE_TEXT_SCHEMA,
    // Delegates to the MCP `fill` tool under the hood.
    'fill',
  );
}

/**
 * Creates declarative tools for all discovered browser MCP tools plus the
 * always-present composite `type_text` tool.
 */
export async function createMcpDeclarativeTools(
  browserManager: BrowserManager,
  messageBus: MessageBus,
): Promise<Array<DeclarativeTool<ToolParams, ToolResult>>> {
  const discovered = await browserManager.getDiscoveredTools();

  const tools: Array<DeclarativeTool<ToolParams, ToolResult>> = discovered.map(
    (tool) =>
      new BrowserMcpTool(
        browserManager,
        messageBus,
        tool.name,
        tool.description ?? '',
        tool.inputSchema ?? { type: 'object', properties: {} },
        tool.name,
      ),
  );

  tools.push(createTypeTextTool(browserManager, messageBus));

  return tools;
}
