import type { Content } from '@google/genai';
import type {
  ToolInvocation,
  ToolResult,
  DeclarativeTool,
} from '../../tools/tools.js';
import { BaseDeclarativeTool, BaseToolInvocation, Kind } from '../../tools/tools.js';
import { ToolErrorType } from '../../tools/tool-error.js';
import type { Config } from '../../config/config.js';
import type { MessageBus } from '../../confirmation-bus/message-bus.js';
import { getResponseText } from '../../utils/partUtils.js';
import { LlmRole } from '../../telemetry/types.js';
import type { BrowserManager } from './browserManager.js';

interface AnalyzeScreenshotParams {
  instruction: string;
}

const ANALYZE_SCREENSHOT_SCHEMA = {
  type: 'object',
  properties: {
    instruction: {
      type: 'string',
      description:
        'What to look for or analyze in the current screenshot (e.g. "find the coordinates of the Submit button").',
    },
  },
  required: ['instruction'],
};

/**
 * Invocation that captures a screenshot and asks a visual model to analyze it.
 */
class AnalyzeScreenshotInvocation extends BaseToolInvocation<
  AnalyzeScreenshotParams,
  ToolResult
> {
  constructor(
    private readonly browserManager: BrowserManager,
    private readonly config: Config,
    params: AnalyzeScreenshotParams,
    messageBus: MessageBus,
    _toolName?: string,
    _toolDisplayName?: string,
  ) {
    super(params, messageBus, _toolName, _toolDisplayName);
  }

  getDescription(): string {
    return `Analyzing screenshot: ${this.params.instruction}`.slice(0, 200);
  }

  async execute(signal: AbortSignal): Promise<ToolResult> {
    // 1. Capture a screenshot via the browser manager.
    let imageItem:
      | { type: 'text' | 'image'; text?: string; data?: string; mimeType?: string }
      | undefined;
    try {
      const shot = await this.browserManager.callTool(
        'take_screenshot',
        {},
        signal,
      );
      imageItem = (shot.content ?? []).find(
        (item) => item.type === 'image' && item.data,
      );
    } catch {
      imageItem = undefined;
    }

    if (!imageItem || !imageItem.data) {
      const message =
        'Failed to capture screenshot for visual analysis. The page may not be ready.';
      return {
        llmContent: message,
        returnDisplay: message,
        error: { message, type: ToolErrorType.EXECUTION_FAILED },
      };
    }

    // 2. Send the screenshot to the visual model for analysis.
    const visualModel =
      this.config.getBrowserAgentConfig().customConfig.visualModel;

    const contents: Content[] = [
      {
        role: 'user',
        parts: [
          {
            inlineData: {
              mimeType: imageItem.mimeType ?? 'image/png',
              data: imageItem.data,
            },
          },
          { text: this.params.instruction },
        ],
      },
    ];

    let text: string | null = null;
    try {
      const response = await this.config.getBaseLlmClient().generateContent({
        modelConfigKey: { model: visualModel ?? '' },
        contents,
        abortSignal: signal,
        promptId: 'browser-agent-analyze-screenshot',
        role: LlmRole.UTILITY_TOOL,
      });
      text = getResponseText(response);
    } catch (error) {
      const errorMsg = error instanceof Error ? error.message : String(error);
      const lower = errorMsg.toLowerCase();
      if (
        lower.includes('404') ||
        lower.includes('403') ||
        lower.includes('not found') ||
        lower.includes('permission')
      ) {
        const message = `Visual analysis model is not available. Check that the configured visualModel exists and is accessible. Details: ${errorMsg}`;
        return {
          llmContent: message,
          returnDisplay: message,
          error: { message, type: ToolErrorType.EXECUTION_FAILED },
        };
      }
      const message = `Visual analysis failed: ${errorMsg}`;
      return {
        llmContent: message,
        returnDisplay: message,
        error: { message, type: ToolErrorType.EXECUTION_FAILED },
      };
    }

    if (!text) {
      const message = 'Visual model returned no analysis.';
      return {
        llmContent: message,
        returnDisplay: message,
        error: { message, type: ToolErrorType.EXECUTION_FAILED },
      };
    }

    const content = `Visual Analysis Result:\n${text}`;
    return {
      llmContent: content,
      returnDisplay: content,
      error: undefined,
    };
  }
}

/**
 * Declarative tool wrapper for {@link AnalyzeScreenshotInvocation}.
 */
class AnalyzeScreenshotTool extends BaseDeclarativeTool<
  AnalyzeScreenshotParams,
  ToolResult
> {
  constructor(
    private readonly browserManager: BrowserManager,
    private readonly config: Config,
    messageBus: MessageBus,
  ) {
    super(
      'analyze_screenshot',
      'Analyze Screenshot',
      'Captures a screenshot of the current page and analyzes it with a visual ' +
        'model according to the given instruction. Useful for locating elements ' +
        'visually and identifying click coordinates.',
      Kind.Read,
      ANALYZE_SCREENSHOT_SCHEMA,
      messageBus,
      /* isOutputMarkdown */ true,
      /* canUpdateOutput */ false,
    );
  }

  protected createInvocation(
    params: AnalyzeScreenshotParams,
    messageBus: MessageBus,
    _toolName?: string,
    _toolDisplayName?: string,
  ): ToolInvocation<AnalyzeScreenshotParams, ToolResult> {
    return new AnalyzeScreenshotInvocation(
      this.browserManager,
      this.config,
      params,
      messageBus,
      _toolName,
      _toolDisplayName,
    );
  }
}

/**
 * Creates the `analyze_screenshot` declarative tool.
 */
export function createAnalyzeScreenshotTool(
  browserManager: BrowserManager,
  config: Config,
  messageBus: MessageBus,
): DeclarativeTool<AnalyzeScreenshotParams, ToolResult> {
  return new AnalyzeScreenshotTool(browserManager, config, messageBus);
}
