/**
 * @fileoverview Factory for constructing the browser agent definition, wiring
 * together the browser manager, discovered MCP tools, and (optionally) the
 * visual analysis tool.
 */

import { z } from 'zod';
import type { Config } from '../../config/config.js';
import type { MessageBus } from '../../confirmation-bus/message-bus.js';
import type { AnyDeclarativeTool } from '../../tools/tools.js';
import type { LocalAgentDefinition } from '../types.js';
import { BrowserManager } from './browserManager.js';
import { createMcpDeclarativeTools } from './mcpToolWrapper.js';
import { createAnalyzeScreenshotTool } from './analyzeScreenshot.js';
import {
  BROWSER_AGENT_DISPLAY_NAME,
  BROWSER_AGENT_NAME,
  buildBrowserSystemPrompt,
} from './browserAgentDefinition.js';

const BrowserAgentOutputSchema = z.object({
  result: z
    .string()
    .describe('A summary of what the browser agent accomplished.'),
});

/**
 * Creates the browser agent definition along with the {@link BrowserManager}
 * instance backing it.
 *
 * Establishes the browser connection, discovers and wraps the MCP tools, and
 * conditionally includes the `analyze_screenshot` tool when a visual model is
 * configured.
 */
export async function createBrowserAgentDefinition(
  config: Config,
  messageBus: MessageBus,
  printOutput?: (msg: string) => void,
): Promise<{
  definition: LocalAgentDefinition<typeof BrowserAgentOutputSchema>;
  browserManager: BrowserManager;
}> {
  const browserManager = new BrowserManager(config);
  await browserManager.ensureConnection();

  printOutput?.('Browser agent connected to Chrome.');

  const tools: AnyDeclarativeTool[] = await createMcpDeclarativeTools(
    browserManager,
    messageBus,
  );

  const visualModel =
    config.getBrowserAgentConfig().customConfig.visualModel;
  const visionEnabled = !!visualModel;

  if (visionEnabled) {
    tools.push(createAnalyzeScreenshotTool(browserManager, config, messageBus));
  }

  const model = config.getBrowserAgentConfig().model;

  const definition: LocalAgentDefinition<typeof BrowserAgentOutputSchema> = {
    kind: 'local',
    name: BROWSER_AGENT_NAME,
    displayName: BROWSER_AGENT_DISPLAY_NAME,
    description:
      'An experimental agent that drives a real Chrome browser to accomplish ' +
      'web-based tasks such as navigation, form filling, and information ' +
      'gathering.',
    experimental: true,
    inputConfig: {
      inputSchema: {
        type: 'object',
        properties: {
          task: {
            type: 'string',
            description:
              'The web task for the browser agent to accomplish, described in ' +
              'natural language.',
          },
        },
        required: ['task'],
      },
    },
    outputConfig: {
      outputName: 'result',
      description: 'A summary of what the browser agent accomplished.',
      schema: BrowserAgentOutputSchema,
    },
    modelConfig: {
      model: model ?? 'inherit',
    },
    promptConfig: {
      systemPrompt: buildBrowserSystemPrompt(visionEnabled),
      query: '${task}',
    },
    runConfig: {
      maxTimeMinutes: 15,
      maxTurns: 30,
    },
    toolConfig: {
      tools,
    },
  };

  return { definition, browserManager };
}

/**
 * Cleans up the browser agent by closing the browser manager. Resolves to
 * undefined even if closing throws.
 */
export async function cleanupBrowserAgent(
  browserManager: BrowserManager,
): Promise<void> {
  try {
    await browserManager.close();
  } catch {
    // Cleanup is best-effort; swallow errors so cleanup never rejects.
  }
}
