import {
  BaseToolInvocation,
  type ToolInvocation,
  type ToolLocation,
  type ToolResult,
} from '../../tools/tools.js';
import type { AnsiOutput } from '../../utils/terminalSerializer.js';
import type { Config } from '../../config/config.js';
import type { MessageBus } from '../../confirmation-bus/message-bus.js';
import type { AgentInputs } from '../types.js';
import { SubagentToolWrapper } from '../subagent-tool-wrapper.js';
import { BROWSER_AGENT_NAME } from './browserAgentDefinition.js';
import {
  cleanupBrowserAgent,
  createBrowserAgentDefinition,
} from './browserAgentFactory.js';

/**
 * A tool invocation that runs the browser agent. It builds the browser agent
 * definition (establishing a browser session), delegates execution to a
 * subagent, and always tears the browser session down afterwards.
 */
export class BrowserAgentInvocation extends BaseToolInvocation<
  AgentInputs,
  ToolResult
> {
  constructor(
    private readonly config: Config,
    params: AgentInputs,
    messageBus: MessageBus,
    toolName?: string,
    toolDisplayName?: string,
  ) {
    super(params, messageBus, toolName ?? BROWSER_AGENT_NAME, toolDisplayName);
  }

  getDescription(): string {
    const keys = Object.keys(this.params).join(', ');
    return `Running browser agent with inputs: ${keys}`.slice(0, 200);
  }

  override toolLocations(): ToolLocation[] {
    return [];
  }

  async execute(
    signal: AbortSignal,
    updateOutput?: (output: string | AnsiOutput) => void,
  ): Promise<ToolResult> {
    const { definition, browserManager } = await createBrowserAgentDefinition(
      this.config,
      this.messageBus,
    );

    try {
      const wrapper = new SubagentToolWrapper(
        definition,
        this.config,
        this.messageBus,
      );
      const invocation: ToolInvocation<AgentInputs, ToolResult> =
        wrapper.build(this.params);
      return await invocation.execute(signal, updateOutput);
    } finally {
      await cleanupBrowserAgent(browserManager);
    }
  }
}
